#!/bin/bash
set -e
perl -0pi -e 's/(\/\/\/ Apply effective ownership only to stored catalogs)/\/\/\/ Whether an encoded manifest retirement state has released any of its artifact\x27s bytes: the\n\/\/\/ complete artifact is evicted, or expiry or eviction has already retired chunks (their\n\/\/\/ references are decremented and unreferenced payload deleted) while the entry stays.\npub(super) fn releases_bytes(bytes: &[u8]) -> Result<bool, Error> {\n    State::decode(bytes).map(|state| state.evicted || state.retired > 0)\n}\n\n$1/' manifest_retire.rs
sed -i 's/manifest_retire::evicted_flag(&bytes)/manifest_retire::releases_bytes(\&bytes)/' payload_index.rs
sed -i 's/^fn valid_payload_id/pub(super) fn valid_payload_id/' import.rs
perl -0pi -e 's/fn digest\(payload_id: &str\) -> Result<&str, Error> \{\n    payload_id\n        \.strip_prefix\("blake3:"\)\n        \.filter\(\|digest\| \{\n.*?\n        \}\)\n        \.ok_or_else/fn digest(payload_id: &str) -> Result<&str, Error> {\n    payload_id\n        .strip_prefix("blake3:")\n        .filter(|_| super::import::valid_payload_id(payload_id))\n        .ok_or_else/s' payload_index.rs
perl -0pi -e 's/ An artifact is indexed exactly while it is complete: its entry exists and\n\/\/! neither the entry nor its manifest retirement state marks it evicted\. This is the same\n\/\/! completeness the per-source counters use, so an artifact that pressure eviction retired\n\/\/! leaves the index in the batch that retires it, and an artifact whose entry is deleted\n\/\/! \(expiry, recordless eviction\) leaves it in the batch that deletes the entry\./ An artifact is indexed exactly while the store holds all of its bytes: its entry\n\/\/! exists, the entry is not marked evicted, and its manifest retirement state has neither\n\/\/! evicted it nor retired any chunk. Expiry and pressure eviction release the bytes before\n\/\/! the entry is deleted (expiry keeps the entry a day past its deadline), so the key leaves\n\/\/! the index in the batch that retires the bytes, not later with the entry. This is stricter\n\/\/! than the per-source counters\x27 completeness, which looks only at the evicted flags. An\n\/\/! artifact whose entry is deleted (recordless eviction) leaves it in that batch too./' payload_index.rs
perl -0pi -e 's/#\[derive\(Clone, Debug, PartialEq, Eq\)\]\npub struct PayloadLookup/#[derive(Clone, Debug, PartialEq, Eq)]\n#[must_use]\npub struct PayloadLookup/' payload_index.rs
